// Runnable demo. Each class would be its own file in a real project.
package com.bank.order;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class OrderDemo {
    private static final Logger log = Logger.getLogger(OrderDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        StateMachine sm = new StateMachine();
        IdempotencyStore idempotency = new IdempotencyStore();

        // Idempotent creation: double-tap sends the SAME key → one order
        String key = "idem-rajesh-001";
        Order order = idempotency.getOrCreate(key, () ->
                new Order("ORD-1", "SAV2001", "CUR3001", new BigDecimal("450.00")));
        Order again = idempotency.getOrCreate(key, () ->
                new Order("ORD-2", "SAV2001", "CUR3001", new BigDecimal("450.00")));
        log.info("Double-tap created same order? " + (order == again) + " id=" + order.id);

        // Happy path transitions via the state machine
        sm.transition(order, OrderEvent.CONFIRM);      // Created → Confirmed
        sm.transition(order, OrderEvent.START_PREP);   // Confirmed → Preparing
        sm.transition(order, OrderEvent.PICK_UP);      // Preparing → PickedUp
        sm.transition(order, OrderEvent.DELIVER);      // PickedUp → Delivered
        log.info("Order " + order.id + " final state = " + order.state);

        // Illegal transition: Delivered → Preparing is rejected
        try {
            sm.transition(order, OrderEvent.START_PREP);
        } catch (IllegalTransitionException e) {
            log.severe("REJECTED illegal transition: " + e.getMessage());
        }

        // Saga with compensation: payment fails → refund + cancel
        Order order2 = new Order("ORD-9", "SAV2001", "CUR3001", new BigDecimal("999.00"));
        OrderSaga saga = new OrderSaga(sm);
        saga.process(order2, /*paymentSucceeds=*/ false);
        log.info("Saga order " + order2.id + " ended in state = " + order2.state);
    }
}

// ─── statemachine/OrderState.java ───
enum OrderState { CREATED, CONFIRMED, PREPARING, PICKED_UP, DELIVERED, CANCELLED, REFUNDED }

// ─── statemachine/OrderEvent.java ───
enum OrderEvent { CONFIRM, START_PREP, PICK_UP, DELIVER, CANCEL, REFUND }

// ─── exception/IllegalTransitionException.java ───
class IllegalTransitionException extends RuntimeException {
    IllegalTransitionException(String m) { super(m); }
}

// ─── model/Order.java ───
class Order {
    final String id, customerId, merchantId; final BigDecimal amount;
    volatile OrderState state = OrderState.CREATED;
    volatile long version = 0;                     // optimistic lock
    final List<String> history = new ArrayList<>();
    Order(String id, String customerId, String merchantId, BigDecimal amount) {
        this.id = id; this.customerId = customerId; this.merchantId = merchantId; this.amount = amount;
        history.add("CREATED");
    }
}

// ─── statemachine/StateMachine.java ───
// Transition table: only defined (state, event) pairs are allowed.
class StateMachine {
    private static final Logger log = Logger.getLogger(StateMachine.class.getName());
    private final Map<OrderState, Map<OrderEvent, OrderState>> table = new EnumMap<>(OrderState.class);

    StateMachine() {
        allow(OrderState.CREATED,   OrderEvent.CONFIRM,    OrderState.CONFIRMED);
        allow(OrderState.CREATED,   OrderEvent.CANCEL,     OrderState.CANCELLED);
        allow(OrderState.CONFIRMED, OrderEvent.START_PREP, OrderState.PREPARING);
        allow(OrderState.CONFIRMED, OrderEvent.CANCEL,     OrderState.CANCELLED);
        allow(OrderState.PREPARING, OrderEvent.PICK_UP,    OrderState.PICKED_UP);
        allow(OrderState.PREPARING, OrderEvent.CANCEL,     OrderState.CANCELLED);
        allow(OrderState.PICKED_UP, OrderEvent.DELIVER,    OrderState.DELIVERED);
        allow(OrderState.DELIVERED, OrderEvent.REFUND,     OrderState.REFUNDED);
        allow(OrderState.CANCELLED, OrderEvent.REFUND,     OrderState.REFUNDED);
    }
    private void allow(OrderState from, OrderEvent event, OrderState to) {
        table.computeIfAbsent(from, k -> new EnumMap<>(OrderEvent.class)).put(event, to);
    }

    synchronized void transition(Order order, OrderEvent event) {
        OrderState from = order.state;
        OrderState to = table.getOrDefault(from, Map.of()).get(event);
        if (to == null) {
            // Idempotency: if the event would re-enter the SAME state, treat as no-op.
            throw new IllegalTransitionException(
                    "cannot apply " + event + " from " + from + " (not in transition table)");
        }
        order.state = to;
        order.version++;                       // optimistic lock bump
        order.history.add(from + " --" + event + "--> " + to);
        log.info("TRANSITION " + order.id + ": " + from + " --" + event + "--> " + to);
        // side effect per transition (emit domain event; real impl publishes to Kafka)
    }
}

