// Coordinates distributed steps via state transitions, with compensation on failure.
class OrderSaga {
    private static final Logger log = Logger.getLogger(OrderSaga.class.getName());
    private final StateMachine sm;
    OrderSaga(StateMachine sm) { this.sm = sm; }

    void process(Order order, boolean paymentSucceeds) {
        try {
            // Step 1: take payment
            if (!paymentSucceeds) throw new RuntimeException("payment declined");
            sm.transition(order, OrderEvent.CONFIRM);          // payment ok → Confirmed
            // Step 2: merchant accepts
            sm.transition(order, OrderEvent.START_PREP);        // → Preparing
            // ... further steps (pickup, deliver) ...
        } catch (RuntimeException ex) {
            log.severe("SAGA step failed: " + ex.getMessage() + " → compensating");
            compensate(order);
        }
    }
    // Compensation: undo in reverse. Here: cancel the order (and refund if money moved).
    private void compensate(Order order) {
        if (order.state == OrderState.CREATED) {
            sm.transition(order, OrderEvent.CANCEL);            // nothing charged → just cancel
        } else {
            sm.transition(order, OrderEvent.CANCEL);
            sm.transition(order, OrderEvent.REFUND);            // refund what was charged
        }
    }
}

// ─── idempotency/IdempotencyStore.java ───
// Create-once: same key returns the first result, never a duplicate.
class IdempotencyStore {
    private final Map<String, Order> byKey = new HashMap<>();
    synchronized Order getOrCreate(String key, java.util.function.Supplier<Order> factory) {
        return byKey.computeIfAbsent(key, k -> factory.get());
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
